-- PAPER-LEARN-MECHANISMS-1 (2026-11-05, charter pillar autonomy, program QNFO.OPS; cluster C8-PROJECTS-GOALS of the roadmap and backlog completion sweep).
-- The PAPER-LEARN-TRIAGE-1 catalogue (paper_learning_mechanisms) held 6 mechanisms, so the triage models answered "apply" to ideas the fleet already runs: 225 probationary learnings read on 2026-11-04 were 115 in place, 93 rejected and 17 routed once read against the real fleet.
-- This file adds the 19 mechanisms those readings cited, each with an evidence probe (one SELECT on qnfo-audit that reads ok while the mechanism works) and a citation. They carry no lexical terms on purpose: a term match settles a learning without a model, and a
-- mechanism is only ever named by the two model families (answer covered or conflicts) and then verified by its probe before a learning is settled. qnfo-lifecycle 1.18.0 (PAPER-LEARN-RETRIAGE-1) reads the larger catalogue.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM paper_learning_mechanisms WHERE mech_key IN ('prediction-before-change', 'metric-bands', 'unmeasured-metric-guard', 'relapse-close-hold', 'belief-registry', 'control-registry', 'blocker-redteam', 'failure-mode-detectors', 'cross-store-accounting', 'outcome-vs-proxy-ledger', 'guard-metrics', 'all-vendor-cost-ledger', 'work-claims-fences', 'issue-throughput-sla', 'human-action-gate', 'deploy-canary-revert', 'probe-attempt-bounds', 'remedy-efficacy-loop', 'research-golden-set')
-- CAUSE-MAPPED: no metric is registered here.

INSERT OR IGNORE INTO paper_learning_mechanisms (mech_key, title, terms, citation, evidence_probe) VALUES
  ('prediction-before-change', 'PREDICT, MEASURE, KEEP OR REVERT: a change logs its predicted outcome before it ships and is compared with the re-measured value after (decision_log predicted_outcome and outcome_matched)', '', 'PROACTIVE-PROGRAMS-1 item 4 and DOCTRINE-1: decision_log carries predicted_outcome, reach_gain, surfaces_tested and outcome_matched; metrics prediction_logged_share_7d and prediction_miss_rate_7d measure it', 'SELECT CASE WHEN CAST((SELECT last_value FROM metric_registry WHERE metric = ''prediction_logged_share_7d'') AS REAL) > 0.5 AND EXISTS (SELECT 1 FROM decision_log WHERE outcome_matched IS NOT NULL) THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('metric-bands', 'Metric warning and kill bands: a metric alerts before its breach threshold, and a trigger is registered with the metric or a named exemption', '', 'metric_registry.warning_band and kill_band (held for most metrics), METRIC-CLOSED-LOOP-1 and METRIC-CAUSE-AT-REGISTRATION-1 in CLAUDE.md', 'SELECT CASE WHEN (SELECT COUNT(*) FROM metric_registry WHERE warning_band IS NOT NULL AND warning_band <> '''') >= 100 THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('unmeasured-metric-guard', 'A metric with no numeric value cannot pass as healthy: the trigger state is unmeasured, not false, and metrics_unmeasured counts those triggers', '', 'v_metric_trigger_state returns hit NULL for a non-numeric value and the guard metric metrics_unmeasured counts enabled triggers that hold no value', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''metrics_unmeasured'') AND EXISTS (SELECT 1 FROM sqlite_master WHERE name = ''v_metric_trigger_state'') THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('relapse-close-hold', 'RELAPSE-HOLD-1: an issue closes only when its passes since the last reopen or failure span a hold by relapse history (20 to 120 minutes), and a failed contract reopens it', '', 'migrations/2026-11-04-relapse-hold-1.sql, view v_issue_close_hold, RELAPSE-COHORT-2 (judged on the channel it governs); trigger issue_refile_reopen reopens a refiled issue', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM sqlite_master WHERE name = ''v_issue_close_hold'') THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('belief-registry', 'Beliefs the fleet acts on are filed with a belief-<key> probe that reads false when the belief fails, and design bets carry a dated check', '', 'DOCTRINE-1: belief_registry with belief-<key> probes; blocker_redteam records false beliefs removed', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM belief_registry) THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('control-registry', 'Every hold, filter, gate or cap is reviewed in control_registry (disposition, critical path, tested alternate), and a single point of failure is recorded in spof_registry', '', 'DOCTRINE-1 and ANTIFRAGILE-1: control_registry, spof_registry, v_doctrine_scorecard_v2 graded each tick', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM control_registry) AND EXISTS (SELECT 1 FROM spof_registry) THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('blocker-redteam', 'A claim of blocked, owner only or cannot is attempted and recorded in blocker_redteam with a verdict before it stands', '', 'ANTIFRAGILE-1 and DOCTRINE-1 section 3: blocker_redteam, v_blocker_claims, metric unverified_blocker_claims', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM blocker_redteam) AND EXISTS (SELECT 1 FROM sqlite_master WHERE name = ''v_blocker_claims'') THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('failure-mode-detectors', 'Every failure mode has a failure_modes row (root cause, blast radius, remediation) and an fm-<key> detector contract that reads within the hour', '', 'ANTIFRAGILE-1: failure_modes and v_failure_mode_status; a recurrence is flagged by failure_modes_recurring', 'SELECT CASE WHEN (SELECT COUNT(*) FROM failure_modes) >= 100 AND EXISTS (SELECT 1 FROM sqlite_master WHERE name = ''v_failure_mode_status'') THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('cross-store-accounting', 'Cross-store reconciliation runs every tick: entered = open + closed + superseded for issues, declared against live bindings, crons and tables in the fleet graph, repository mirrors against workers', '', 'v_issue_accounting (metrics silent_drops, issues_unaccounted), the fleet graph findings (fleet_graph_findings_warn), mirror-guard and version-bump-guard', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM sqlite_master WHERE name = ''v_issue_accounting'') AND EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''silent_drops'') AND EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''fleet_graph_findings_warn'') THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('outcome-vs-proxy-ledger', 'Quality is read from outcome measures only: a rule-based score is labelled proxy and never a target, a pool mean is not evidence, and an unmeasured outcome is never a pass', '', 'OUTPUT-QUALITY-LEDGER-1 (docs/OUTPUT-QUALITY-LEDGER.md): output_quality_measures, v_output_quality_by_surface, READER-YIELD-1 (clicks are not readers)', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM output_quality_measures) AND EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''output_quality_outcomes_unmeasured'') THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('guard-metrics', 'A target metric that improves while a guard metric worsens is a regression: guard metrics keep the closed loop honest', '', 'INTEGRITY-GUARDS-1: metric_registry kind guard (issue_wontfix_share_7d, remediation_latest_pass_pct_7d, cost guards), METRIC-CLOSED-LOOP-1', 'SELECT CASE WHEN (SELECT COUNT(*) FROM metric_registry WHERE kind = ''guard'') >= 20 THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('all-vendor-cost-ledger', 'Cost is a measured ledger across every vendor, not only per-call AI spend: fixed and owner-stated lines sit beside metered ones', '', 'COST-LEDGER-ALLVENDOR-1: view v_cost_all_in (measured, estimated and owner-stated USD, month-to-date and forecast), cost_daily, and the standing goal external-impact-per-dollar', 'SELECT CASE WHEN (SELECT lines FROM v_cost_all_in) > 0 THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('work-claims-fences', 'Concurrent sessions claim independent items and a claim expires with a fence counter; a lapsed claim with the work undone is taken over', '', 'WORK-CLAIM-1: qnfo-deploy-guard /work-lock/acquire, the work_claims ledger in qnfo-audit, GET /work-locks', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM work_claims) THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('issue-throughput-sla', 'Issues drain faster than they open and no item is stuck past 120 minutes: drain ratio, age ladder and per-family net inflow are measured every tick', '', 'ISSUE-THROUGHPUT-1 and QUEUE-SLA-1: metrics issue_drain_ratio_24h, issues_open_over_120m, stuck_items_over_sla, view v_issue_family_throughput', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''issue_drain_ratio_24h'') AND EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''issues_open_over_120m'') THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('human-action-gate', 'Work only the owner can do is isolated as an IDENTITY-BOUND card with a closing probe; everything else is rerouted to the fleet, and the loops keep draining other work', '', 'AUTONOMY-FIRST-1: human_actions, view v_human_action_gate, the default-approve decision path', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM human_actions) AND EXISTS (SELECT 1 FROM sqlite_master WHERE name = ''v_human_action_gate'') THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('deploy-canary-revert', 'A deploy is probed before and after: routes and D1 statements declared per worker, a regression reverts the push, and a control-plane worker is canaried for its new version', '', 'DEPLOY-PROBES-1 (scripts/deploy_probes.py, scripts/canary_revert.py) and CONTROL-PLANE-SELF-MERGE-1; canary-functional events record each run', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''canary-functional'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-2 days'')) THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('probe-attempt-bounds', 'A probe is bounded: max_attempts and budget_ms per contract, an over-retried contract is parked as escalated, and loops cap their batch per tick', '', 'remediation_contracts.max_attempts, max_items and budget_ms; the escalated:over-retried verdict; per-tick caps such as PL_TRIAGE_EXAMINE', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM remediation_contracts WHERE max_attempts > 0 AND budget_ms > 0) THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('remedy-efficacy-loop', 'A remedy is judged by whether it moved its metric within 7 days and replaced, not repeated, when it did not; a wrong target is corrected with evidence', '', 'METRIC-CLOSED-LOOP-1: metric_registry, v_metric_trigger_state, analytics_metric_triggers, and the metric remedy_efficacy_30d', 'SELECT CASE WHEN CAST((SELECT last_value FROM metric_registry WHERE metric = ''remedy_efficacy_30d'') AS REAL) >= 0 THEN ''ok'' ELSE ''absent'' END AS observed'),
  ('research-golden-set', 'Fixed-answer canaries exist beside ensemble agreement: a golden research set and the CF-MODEL-EVAL-1 battery with known answers', '', 'research_golden_runs, qnfo-chat-canary, cf_model_eval_runs (qnfo-model-eval)', 'SELECT CASE WHEN EXISTS (SELECT 1 FROM research_golden_runs) OR EXISTS (SELECT 1 FROM cf_model_eval_runs) THEN ''ok'' ELSE ''absent'' END AS observed');
